rest.assertionCode:
def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 400 or not isinstance(responseBody, dict):
        return False
    if not (isinstance(responseBody.get('code'), int) and (not isinstance(responseBody.get('code'), bool))) or responseBody['code'] != 40001:
        return False
    message = responseBody.get('message')
    request_id = responseBody.get('requestId')
    if not isinstance(message, str) or not isinstance(request_id, str) or (not request_id.strip()):
        return False
    field_identified = any((value in message.lower() for value in ('identitytype', 'identity_type', '身份类型')))
    return field_identified and 'data' in responseBody and (responseBody['data'] is None)
